import React from 'react';
import { CloseCircleOutlined } from '@ant-design/icons';
import { Button, Layout, Result, Typography, Spin } from 'antd';
import { useNavigation } from '../router/routerContext';
import { apiClientInstance } from '../api/ClientApi';
import { Content } from 'antd/es/layout/layout';

const { Paragraph, Text } = Typography;

const AuthPage: React.FC = () => {
    const { navigateTo } = useNavigation();
    const [isCheckingToken, setIsCheckingToken] = React.useState(true);
    const [tokenReceived, setTokenReceived] = React.useState(false);
    const [token , setToken] = React.useState("")

    React.useEffect(() => {
        const checkTokenValidity = async () => {
            const token = await window.NativeBridge.get("token");
            setToken(token)
            if (token == null) {
                console.error('Token validation error:', "token is null");
                setIsCheckingToken(false);
                return;
            }

            apiClientInstance.setToken(token)

            try {
                const isValid = await apiClientInstance.validateToken();
                if (isValid) {
                    navigateTo("main");
                } else {
                    setIsCheckingToken(false);
                }
            } catch (error) {
                console.error('Token validation error:', error);
                setIsCheckingToken(false);
            }
        };

        checkTokenValidity();
        window.NativeBridge.set("token", "TEST"+Math.random())

        const off = window.NativeBridge.on("deeplink", (url) => {
            const token = extractTokenFromUrl(url);
            if (token) {
                window.NativeBridge.set("token", token)
                apiClientInstance.setToken(token);
                setTokenReceived(true);
                setIsCheckingToken(true);
                checkTokenValidity();
            }
        });

        return () => {
            off();
        };
    }, [navigateTo]);

    const extractTokenFromUrl = (url: string): string | null => {
        return "test";
    };

    if (isCheckingToken) {
        return (
            <Layout style={{ minHeight: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <Spin size="large" tip={tokenReceived ? "Проверка нового токена..." : "Проверка токена..."} />
            </Layout>
        );
    }

    return (
        <Layout style={{ minHeight: '100vh' }}>
            <Result
                status="error"
                title={"Требуется аутентификация "+ token}
                subTitle="Пожалуйста, авторизуйтесь в телегараме для доступа к приложению."
                extra={[
                    <Button type="primary" key="retry" onClick={() => window.location.reload()}>
                        Повторить
                    </Button>,
                    <Button type="default" key="redirect" onClick={() => window.open("https://web.telegram.org/k/#@PakiVPN_Bot", '_blank', 'noopener,noreferrer')}>
                        Перейти в бота
                    </Button>,
                ]}
            >
                <div className="desc">
                    <Paragraph>
                        <Text strong style={{ fontSize: 16 }}>
                            Проверка токена не удолась возможные причины этого:
                        </Text>
                    </Paragraph>
                    <Paragraph>
                        <CloseCircleOutlined className="site-result-demo-error-icon" /> Действительный токен не найден
                    </Paragraph>
                    <Paragraph>
                        <CloseCircleOutlined className="site-result-demo-error-icon" /> Ожидание аутентификации через deeplink
                    </Paragraph>
                    <Paragraph>
                        <CloseCircleOutlined className="site-result-demo-error-icon" /> Сервис не доступен
                    </Paragraph>
                </div>
            </Result>
        </Layout>
    );
};

export default AuthPage;